using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using Smartlog.Domain.Entities.Vas;
using Smartlog.Infrastructure.EntityFramework;
using Smartlog.Infrastructure.EntityFramework.Configurations;

namespace Smartlog.Infrastructure.EntityFramework.Configurations.Vas;

public class VasWorkOrderConfiguration : IEntityTypeConfiguration<VasWorkOrder>
{
    public void Configure(EntityTypeBuilder<VasWorkOrder> builder)
    {
        builder.ToTable("vas_work_order", DatabaseConstants.Schemas.Operation);
        builder.ConfigureTenantDefault();

        builder.Property(e => e.VwoNumber).HasColumnName("vwo_number").HasMaxLength(50).IsRequired();
        builder.Property(e => e.ServiceType).HasColumnName("service_type").HasConversion<string>().HasMaxLength(20);
        builder.Property(e => e.BomId).HasColumnName("bom_id").IsRequired();
        builder.Property(e => e.OwnerId).HasColumnName("owner_id").IsRequired();
        builder.Property(e => e.WarehouseId).HasColumnName("warehouse_id").IsRequired();
        builder.Property(e => e.TargetItemId).HasColumnName("target_item_id").IsRequired();
        builder.Property(e => e.TargetLotId).HasColumnName("target_lot_id");
        builder.Property(e => e.PlannedQty).HasColumnName("planned_qty").HasPrecision(18, 3);
        builder.Property(e => e.ActualQty).HasColumnName("actual_qty").HasPrecision(18, 3);
        builder.Property(e => e.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(20);
        builder.Property(e => e.Notes).HasColumnName("notes").HasMaxLength(1000);

        builder.HasIndex(e => new { e.TenantId, e.VwoNumber }).IsUnique();

        builder.HasOne(e => e.Bom).WithMany().HasForeignKey(e => e.BomId).OnDelete(DeleteBehavior.Restrict);
        builder.HasOne(e => e.Owner).WithMany().HasForeignKey(e => e.OwnerId).OnDelete(DeleteBehavior.Restrict);
        builder.HasOne(e => e.Warehouse).WithMany().HasForeignKey(e => e.WarehouseId).OnDelete(DeleteBehavior.Restrict);
        builder.HasOne(e => e.TargetItem).WithMany().HasForeignKey(e => e.TargetItemId).OnDelete(DeleteBehavior.Restrict);
        builder.HasOne(e => e.TargetLot).WithMany().HasForeignKey(e => e.TargetLotId).OnDelete(DeleteBehavior.Restrict);
    }
}

