public class ConfirmVasSession
{
    public record Command(
        Guid VwoId,
        Guid SessionId,
        decimal OutputQty,
        Guid TargetLocationId,
        List<SessionLineInput> Lines
    ) : ICommand;

    public record SessionLineInput(
        Guid VwoSourceId,
        Guid SourceItemId,
        Guid SourceLotId,
        Guid SourceLocationId,
        decimal ConsumedQty
    );

    public class CommandHandler(
        IAppDbContext context,
        IInventTransService inventTransService,
        IInventDimService inventDimService,
        ILogger<CommandHandler> logger) : ICommandHandler<Command>
    {
        public async Task HandleAsync(Command command, CancellationToken cancellationToken = default)
        {
            var session = await context.VasSessions
                .Include(s => s.VasWorkOrder)
                    .ThenInclude(vwo => vwo.Bom)
                        .ThenInclude(b => b.Lines)
                .FirstOrDefaultAsync(s => s.Id == command.SessionId && s.VwoId == command.VwoId, cancellationToken)
                ?? throw BusinessRule.VasSession.NotFound.ToBusinessException([command.SessionId]);

            // BR-VAS-009
            if (session.Status != VasSessionStatus.Open)
                throw BusinessRule.VasSession.NotOpen.ToBusinessException();

            // BR-VAS-004 — validate completeness
            if (command.OutputQty <= 0) throw ...;
            if (command.TargetLocationId == Guid.Empty) throw ...;

            var vwo = session.VasWorkOrder;
            var bom = vwo.Bom;

            // Build InventTrans commands
            var issueCmds = new List<InventTransCommand>();
            foreach (var line in command.Lines)
            {
                // BR-VAS-010 — available qty check
                // ... check available qty

                var bomLine = bom.Lines.First(l => /* match source_item_id from vwo_source */);
                // BR-VAS-005: skip CLIENT_OWNED
                if (bomLine.IsPackagingMaterial && bomLine.PackagingOwnership == PackagingOwnership.ClientOwned)
                    continue;

                var dimId = await inventDimService.GetOrCreateAsync(
                    vwo.WarehouseId, line.SourceLocationId, vwo.OwnerId,
                    InventoryStatusCode.Available, line.SourceLotId, cancellationToken);

                var item = await context.Items.FirstAsync(i => i.Id == line.SourceItemId, cancellationToken);
                issueCmds.Add(new InventTransCommand(
                    line.SourceItemId, dimId,
                    TransType.Issue, TransStage.Deducted,
                    -line.ConsumedQty, null, null, item.BaseUomId,
                    "VAS", session.Id, null));
            }

            // BR-VAS-006: skip RECEIPT for DE_BAGGING
            if (bom.ServiceType != VasType.DeBagging)
            {
                var receiptDimId = await inventDimService.GetOrCreateAsync(
                    vwo.WarehouseId, command.TargetLocationId, vwo.OwnerId,
                    InventoryStatusCode.Available, vwo.TargetLotId, cancellationToken);
                var targetItem = await context.Items.FirstAsync(i => i.Id == vwo.TargetItemId, cancellationToken);
                await inventTransService.PostAsync(new InventTransCommand(
                    vwo.TargetItemId, receiptDimId,
                    TransType.Receipt, TransStage.Physical,
                    command.OutputQty, null, null, targetItem.BaseUomId,
                    "VAS", session.Id, null), cancellationToken);
            }

            if (issueCmds.Count > 0)
                await inventTransService.PostBatchAsync(issueCmds, Guid.NewGuid(), cancellationToken);

            // Update session state
            session.Status = VasSessionStatus.Confirmed;
            session.OutputQty = command.OutputQty;
            session.TargetLocationId = command.TargetLocationId;
            session.ConfirmedAt = DateTime.UtcNow;
            vwo.ActualQty += command.OutputQty;

            await context.SaveChangesAsync(cancellationToken);
        }
    }
}

