using Smartlog.Application.Features.Vas.WorkOrders.Commands;
using Smartlog.Application.Features.Vas.WorkOrders.Dtos;
using Smartlog.Application.Features.Vas.WorkOrders.Queries;
using Smartlog.Application.Features.Vas.Sessions.Commands;
using Smartlog.Application.Features.Vas.Sessions.Queries;

namespace Smartlog.Api.Controllers;

[ApiController]
[Route("api/vas-work-orders")]
[Authorize]
public sealed class VasWorkOrdersController(IDispatcher dispatcher) : ControllerBase
{
    [HttpGet]
    public async Task<IActionResult> GetList([FromQuery] int page = 1, [FromQuery] int pageSize = 10,
        [FromQuery] string? formCode = "OPSVWOG01", CancellationToken ct = default)
    {
        var result = await dispatcher.QueryAsync(new GetVasWorkOrderList.Query { Page = page, PageSize = pageSize, FormCode = formCode ?? "OPSVWOG01" }, ct);
        return Ok(ApiResult<DynamicGridResult>.Success(result));
    }

    [HttpPost("search")]
    public async Task<IActionResult> Search([FromBody] GetVasWorkOrderList.Query query, CancellationToken ct)
    {
        var result = await dispatcher.QueryAsync(query, ct);
        return Ok(ApiResult<DynamicGridResult>.Success(result));
    }

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> GetById(Guid id, CancellationToken ct)
    {
        var result = await dispatcher.QueryAsync(new GetVasWorkOrderById.Query(id), ct);
        if (result == null) return NotFound();
        return Ok(ApiResult<VasWorkOrderDetailDto>.Success(result));
    }

    [HttpPost]
    public async Task<IActionResult> Create([FromBody] CreateVasWorkOrder.Command command, CancellationToken ct)
    {
        var id = await dispatcher.DispatchAsync(command, ct);
        return StatusCode(StatusCodes.Status201Created, ApiResult<Guid>.Success(id));
    }

    [HttpPost("{id:guid}/confirm")]
    public async Task<IActionResult> Confirm(Guid id, [FromBody] ConfirmVasWorkOrder.Command command, CancellationToken ct)
    {
        await dispatcher.DispatchAsync(command with { Id = id }, ct);
        return NoContent();
    }

    [HttpPost("{id:guid}/complete")]
    public async Task<IActionResult> Complete(Guid id, CancellationToken ct)
    {
        await dispatcher.DispatchAsync(new CompleteVasWorkOrder.Command(id), ct);
        return NoContent();
    }

    [HttpPost("{id:guid}/cancel")]
    public async Task<IActionResult> Cancel(Guid id, CancellationToken ct)
    {
        await dispatcher.DispatchAsync(new CancelVasWorkOrder.Command(id), ct);
        return NoContent();
    }

    // Sessions nested under WO
    [HttpPost("{vwoId:guid}/sessions")]
    public async Task<IActionResult> OpenSession(Guid vwoId, [FromBody] OpenVasSession.Command command, CancellationToken ct)
    {
        var id = await dispatcher.DispatchAsync(command with { VwoId = vwoId }, ct);
        return StatusCode(StatusCodes.Status201Created, ApiResult<Guid>.Success(id));
    }

    [HttpPost("{vwoId:guid}/sessions/{id:guid}/confirm")]
    public async Task<IActionResult> ConfirmSession(Guid vwoId, Guid id, [FromBody] ConfirmVasSession.Command command, CancellationToken ct)
    {
        await dispatcher.DispatchAsync(command with { VwoId = vwoId, SessionId = id }, ct);
        return NoContent();
    }

    [HttpPost("{vwoId:guid}/sessions/{id:guid}/cancel")]
    public async Task<IActionResult> CancelSession(Guid vwoId, Guid id, CancellationToken ct)
    {
        await dispatcher.DispatchAsync(new CancelVasSession.Command(vwoId, id), ct);
        return NoContent();
    }
}

