import { apiClient } from '@/lib/api-client'
import type { DynamicGridResult } from '@/types/api'

export interface CreateVasWorkOrderCommand {
  serviceType: string
  bomId: string
  ownerId: string
  warehouseId: string
  plannedQty: number
  notes?: string | null
}

export interface ConfirmVasWorkOrderCommand {
  sourceLots: ConfirmSourceLot[]
}

export interface ConfirmSourceLot {
  bomLineId: string
  sourceItemId: string
  sourceLotId: string
  allocatedQty: number
}

export interface ConfirmVasSessionCommand {
  outputQty: number
  targetLocationId: string
  lines: ConfirmSessionLine[]
}

export interface ConfirmSessionLine {
  vwoSourceId: string
  sourceItemId: string
  sourceLotId: string
  sourceLocationId: string
  consumedQty: number
}

interface SearchParams {
  formCode?: string
  searchFormCode?: string
  filterValues?: Record<string, unknown>
  [key: string]: unknown
}

export const vasWorkOrderApi = {
  getList: async (params: SearchParams) => {
    const response = await apiClient.post('/vas-work-orders/search', {
      ...params,
      formCode: params.formCode ?? 'OPSVWOG01',
      searchFormCode: params.searchFormCode ?? 'OPSVWOS01',
      filterValues: params.filterValues ?? {},
    })
    return response.data.data as DynamicGridResult
  },

  getById: async (id: string) => {
    const response = await apiClient.get(`/vas-work-orders/${id}`)
    return response.data.data
  },

  create: async (data: CreateVasWorkOrderCommand) => {
    const response = await apiClient.post('/vas-work-orders', data)
    return response.data.data as string
  },

  confirm: async (id: string, data: ConfirmVasWorkOrderCommand) => {
    await apiClient.post(`/vas-work-orders/${id}/confirm`, data)
  },

  complete: async (id: string) => {
    await apiClient.post(`/vas-work-orders/${id}/complete`)
  },

  cancel: async (id: string) => {
    await apiClient.post(`/vas-work-orders/${id}/cancel`)
  },

  openSession: async (vwoId: string, data?: { isOvertime?: boolean; notes?: string }) => {
    const response = await apiClient.post(`/vas-work-orders/${vwoId}/sessions`, data ?? {})
    return response.data.data as string
  },

  confirmSession: async (vwoId: string, sessionId: string, data: ConfirmVasSessionCommand) => {
    await apiClient.post(`/vas-work-orders/${vwoId}/sessions/${sessionId}/confirm`, data)
  },

  cancelSession: async (vwoId: string, sessionId: string) => {
    await apiClient.post(`/vas-work-orders/${vwoId}/sessions/${sessionId}/cancel`)
  },
}

